-- PELEX GROUPS: profiles, rooms, membership, messages and support queue.
create table if not exists public.member_profiles(user_id uuid primary key references auth.users(id) on delete cascade,pelex_id text not null unique,emoji text not null default '🙂',first_name text,created_at timestamptz not null default now());
create table if not exists public.rooms(id uuid primary key default gen_random_uuid(),room_code text not null unique,name text not null,emoji text not null default '💬',invite_token text not null unique,created_by uuid references auth.users(id) on delete set null,pelex_called_at timestamptz,created_at timestamptz not null default now());
create table if not exists public.room_members(room_id uuid not null references public.rooms(id) on delete cascade,user_id uuid not null references auth.users(id) on delete cascade,role text not null default 'member' check(role in('owner','member')),joined_at timestamptz not null default now(),primary key(room_id,user_id));
create index if not exists room_members_user_idx on public.room_members(user_id);
create table if not exists public.room_messages(id bigint generated always as identity primary key,room_id uuid not null references public.rooms(id) on delete cascade,user_id uuid references auth.users(id) on delete set null,kind text not null default 'user' check(kind in('user','pelex','system')),content text not null check(length(content) between 1 and 4000),created_at timestamptz not null default now());
create index if not exists room_messages_room_idx on public.room_messages(room_id,id);
create table if not exists public.support_requests(id uuid primary key default gen_random_uuid(),room_id uuid not null references public.rooms(id) on delete cascade,requested_by uuid references auth.users(id) on delete set null,note text,status text not null default 'open' check(status in('open','joined','closed')),created_at timestamptz not null default now());
alter table public.member_profiles enable row level security; alter table public.rooms enable row level security; alter table public.room_members enable row level security; alter table public.room_messages enable row level security; alter table public.support_requests enable row level security;
revoke all on public.member_profiles,public.rooms,public.room_members,public.room_messages,public.support_requests from anon,authenticated;
grant select on public.member_profiles,public.rooms,public.room_members,public.room_messages to authenticated; grant insert on public.room_messages to authenticated;
create or replace function public.is_room_member(p_room uuid) returns boolean language sql security definer stable set search_path=public as $$ select exists(select 1 from public.room_members where room_id=p_room and user_id=auth.uid()); $$;
drop policy if exists "own profile" on public.member_profiles; create policy "own profile" on public.member_profiles for select to authenticated using(user_id=auth.uid());
drop policy if exists "my rooms" on public.rooms; create policy "my rooms" on public.rooms for select to authenticated using(public.is_room_member(id));
drop policy if exists "my room members" on public.room_members; create policy "my room members" on public.room_members for select to authenticated using(public.is_room_member(room_id));
drop policy if exists "read room messages" on public.room_messages; create policy "read room messages" on public.room_messages for select to authenticated using(public.is_room_member(room_id));
drop policy if exists "send room messages" on public.room_messages; create policy "send room messages" on public.room_messages for insert to authenticated with check(public.is_room_member(room_id) and user_id=auth.uid() and kind='user');
create or replace function public.gen_code(p_prefix text,p_len int) returns text language plpgsql volatile set search_path=public as $$ declare a text:='23456789ABCDEFGHJKLMNPQRSTUVWXYZ'; r text:=''; i int; begin for i in 1..p_len loop r:=r||substr(a,1+floor(random()*length(a))::int,1); end loop; return p_prefix||r; end $$;
create or replace function public.ensure_profile(p_emoji text default null) returns jsonb language plpgsql security definer set search_path=public as $$
declare uid uuid:=auth.uid(); code text; fn text; begin
if uid is null then raise exception 'Please sign in first.'; end if;
if not exists(select 1 from member_profiles where user_id=uid) then
select split_part(coalesce(nullif(u.raw_user_meta_data->>'full_name',''),nullif(u.raw_user_meta_data->>'name',''),split_part(u.email,'@',1),'Member'),' ',1) into fn from auth.users u where u.id=uid;
loop code:=gen_code('PLX-',6); exit when not exists(select 1 from member_profiles m where m.pelex_id=code); end loop;
insert into member_profiles(user_id,pelex_id,emoji,first_name) values(uid,code,coalesce(nullif(left(p_emoji,8),''),'🙂'),left(coalesce(fn,'Member'),30));
elsif p_emoji is not null and p_emoji<>'' then update member_profiles set emoji=left(p_emoji,8) where user_id=uid; end if;
return(select jsonb_build_object('pelex_id',m.pelex_id,'emoji',m.emoji,'first_name',m.first_name) from member_profiles m where m.user_id=uid); end $$;
create or replace function public.find_person(p_id text) returns jsonb language plpgsql security definer stable set search_path=public as $$ declare k text:=upper(regexp_replace(coalesce(p_id,''),'\s','','g')); begin if auth.uid() is null then raise exception 'Please sign in first.'; end if; if k !~ '^PLX-[A-Z0-9]{6}$' then return null; end if; return(select jsonb_build_object('pelex_id',m.pelex_id,'emoji',m.emoji,'first_name',m.first_name) from member_profiles m where m.pelex_id=k); end $$;
create or replace function public.create_room(p_name text,p_emoji text default null) returns jsonb language plpgsql security definer set search_path=public as $$
declare uid uuid:=auth.uid(); rid uuid; code text; tok text; nm text:=left(trim(coalesce(p_name,'')),60); begin
if uid is null then raise exception 'Please sign in first.'; end if; if length(nm)<1 then raise exception 'Give your group a name first.'; end if; perform ensure_profile(null);
if(select count(*) from room_members where user_id=uid and role='owner')>=20 then raise exception 'You have reached the limit of 20 groups you own.'; end if;
loop code:=gen_code('GRP-',6); exit when not exists(select 1 from rooms r where r.room_code=code); end loop; tok:=replace(gen_random_uuid()::text,'-','');
insert into rooms(name,emoji,room_code,invite_token,created_by) values(nm,coalesce(nullif(left(p_emoji,8),''),'💬'),code,tok,uid) returning id into rid;
insert into room_members(room_id,user_id,role) values(rid,uid,'owner'); insert into room_messages(room_id,user_id,kind,content) values(rid,null,'system','Group created.'); return jsonb_build_object('id',rid,'room_code',code); end $$;
create or replace function public.my_rooms() returns jsonb language sql security definer stable set search_path=public as $$ select coalesce(jsonb_agg(q.x order by q.x->>'last_at' desc),'[]'::jsonb) from(select jsonb_build_object('id',r.id,'name',r.name,'emoji',r.emoji,'room_code',r.room_code,'role',m.role,'invite_token',r.invite_token,'members',(select count(*) from room_members mm where mm.room_id=r.id),'last_at',coalesce((select max(g.created_at) from room_messages g where g.room_id=r.id),r.created_at)) as x from room_members m join rooms r on r.id=m.room_id where m.user_id=auth.uid()) q; $$;
create or replace function public.room_members_info(p_room uuid) returns jsonb language plpgsql security definer set search_path=public as $$ begin if not is_room_member(p_room) then raise exception 'You are not in this group.'; end if; return coalesce((select jsonb_agg(jsonb_build_object('user_id',m.user_id,'pelex_id',p.pelex_id,'emoji',p.emoji,'first_name',p.first_name,'role',m.role) order by m.joined_at) from room_members m left join member_profiles p on p.user_id=m.user_id where m.room_id=p_room),'[]'::jsonb); end $$;
create or replace function public.join_room_by_token(p_token text) returns jsonb language plpgsql security definer set search_path=public as $$ declare uid uuid:=auth.uid(); r rooms; who jsonb; begin if uid is null then raise exception 'Please sign in first.'; end if; select * into r from rooms where invite_token=p_token; if not found then raise exception 'That invite link is no longer valid.'; end if; who:=ensure_profile(null); if exists(select 1 from room_members where room_id=r.id and user_id=uid) then return jsonb_build_object('id',r.id,'name',r.name,'already',true); end if; if(select count(*) from room_members where room_id=r.id)>=50 then raise exception 'This group is full (50 people).'; end if; insert into room_members(room_id,user_id,role) values(r.id,uid,'member'); insert into room_messages(room_id,user_id,kind,content) values(r.id,null,'system',(who->>'first_name')||' joined with the invite link.'); return jsonb_build_object('id',r.id,'name',r.name,'already',false); end $$;
create or replace function public.add_member_by_id(p_room uuid,p_pelex_id text) returns jsonb language plpgsql security definer set search_path=public as $$ declare uid uuid:=auth.uid(); k text:=upper(regexp_replace(coalesce(p_pelex_id,''),'\s','','g')); t member_profiles; me jsonb; begin if uid is null then raise exception 'Please sign in first.'; end if; if not is_room_member(p_room) then raise exception 'You are not in this group.'; end if; select * into t from member_profiles where pelex_id=k; if not found then raise exception 'No one was found with that ID.'; end if; if exists(select 1 from room_members where room_id=p_room and user_id=t.user_id) then return jsonb_build_object('already',true,'first_name',t.first_name); end if; if(select count(*) from room_members where room_id=p_room)>=50 then raise exception 'This group is full (50 people).'; end if; insert into room_members(room_id,user_id,role) values(p_room,t.user_id,'member'); select jsonb_build_object('first_name',first_name) into me from member_profiles where user_id=uid; insert into room_messages(room_id,user_id,kind,content) values(p_room,null,'system',t.first_name||' was added by '||coalesce(me->>'first_name','a member')||'.'); return jsonb_build_object('already',false,'first_name',t.first_name); end $$;
create or replace function public.leave_room(p_room uuid) returns void language plpgsql security definer set search_path=public as $$ declare uid uuid:=auth.uid(); was text; nm text; begin if uid is null then raise exception 'Please sign in first.'; end if; select role into was from room_members where room_id=p_room and user_id=uid; if not found then return; end if; select first_name into nm from member_profiles where user_id=uid; delete from room_members where room_id=p_room and user_id=uid; if not exists(select 1 from room_members where room_id=p_room) then delete from rooms where id=p_room; return; end if; if was='owner' and not exists(select 1 from room_members where room_id=p_room and role='owner') then update room_members set role='owner' where room_id=p_room and user_id=(select user_id from room_members where room_id=p_room order by joined_at limit 1); end if; insert into room_messages(room_id,user_id,kind,content) values(p_room,null,'system',coalesce(nm,'A member')||' left the group.'); end $$;
create or replace function public.remove_member(p_room uuid,p_pelex_id text) returns void language plpgsql security definer set search_path=public as $$ declare uid uuid:=auth.uid(); t member_profiles; begin if not exists(select 1 from room_members where room_id=p_room and user_id=uid and role='owner') then raise exception 'Only the group owner can remove people.'; end if; select * into t from member_profiles where pelex_id=upper(regexp_replace(coalesce(p_pelex_id,''),'\s','','g')); if not found or t.user_id=uid then return; end if; delete from room_members where room_id=p_room and user_id=t.user_id; insert into room_messages(room_id,user_id,kind,content) values(p_room,null,'system',t.first_name||' was removed.'); end $$;
create or replace function public.reset_invite(p_room uuid) returns text language plpgsql security definer set search_path=public as $$ declare tok text:=replace(gen_random_uuid()::text,'-',''); begin if not exists(select 1 from room_members where room_id=p_room and user_id=auth.uid() and role='owner') then raise exception 'Only the group owner can reset the invite link.'; end if; update rooms set invite_token=tok where id=p_room; return tok; end $$;
create or replace function public.call_pelex(p_room uuid,p_note text default null) returns jsonb language plpgsql security definer set search_path=public as $$ declare uid uuid:=auth.uid(); last_at timestamptz; begin if uid is null then raise exception 'Please sign in first.'; end if; if not is_room_member(p_room) then raise exception 'You are not in this group.'; end if; select pelex_called_at into last_at from rooms where id=p_room; if last_at is not null and last_at>now()-interval '10 minutes' then return jsonb_build_object('already',true); end if; insert into support_requests(room_id,requested_by,note) values(p_room,uid,left(p_note,500)); update rooms set pelex_called_at=now() where id=p_room; insert into room_messages(room_id,user_id,kind,content) values(p_room,null,'system','Pelex Support has been notified and will join this chat when available.'); return jsonb_build_object('already',false); end $$;
revoke execute on all functions in schema public from public,anon;
grant execute on function public.is_room_member(uuid),public.ensure_profile(text),public.find_person(text),public.create_room(text,text),public.my_rooms(),public.room_members_info(uuid),public.join_room_by_token(text),public.add_member_by_id(uuid,text),public.leave_room(uuid),public.remove_member(uuid,text),public.reset_invite(uuid),public.call_pelex(uuid,text) to authenticated;
revoke execute on function public.gen_code(text,int) from authenticated;
do $$ begin alter publication supabase_realtime add table public.room_messages; exception when duplicate_object then null; when undefined_object then null; end $$;
select t.n,to_regclass('public.'||t.n) is not null as exists_now from(values('member_profiles'),('rooms'),('room_members'),('room_messages'),('support_requests')) as t(n);
